package com.bjjj.todo;
import org.json.*;import java.util.*;
final class SyncProtocol {
 static final String[] TEXT={"id","title","due","priority","category","notes","created","completed"};
 static JSONObject payload(JSONObject t)throws JSONException{JSONObject p=new JSONObject();for(String k:TEXT)p.put(k,t.optString(k,""));if(p.optString("priority").isEmpty())p.put("priority","normal");if(p.optString("category").isEmpty())p.put("category","other");p.put("done",t.optBoolean("done"));p.put("offsets",t.optJSONArray("offsets")==null?new JSONArray():t.getJSONArray("offsets"));return p;}
 static String canonical(Object v)throws JSONException{if(v instanceof JSONObject o){List<String> keys=new ArrayList<>();o.keys().forEachRemaining(keys::add);Collections.sort(keys);StringBuilder out=new StringBuilder("{");for(String k:keys)out.append(JSONObject.quote(k)).append(':').append(canonical(o.get(k))).append(',');return out.append('}').toString();}if(v instanceof JSONArray a){StringBuilder out=new StringBuilder("[");for(int i=0;i<a.length();i++)out.append(canonical(a.get(i))).append(',');return out.append(']').toString();}if(v==null||v==JSONObject.NULL)return "null";if(v instanceof String)return JSONObject.quote((String)v);if(v instanceof Number)return new java.math.BigDecimal(v.toString()).stripTrailingZeros().toPlainString();return v.toString();}
 static boolean eq(Object a,Object b)throws JSONException{return Objects.equals(a==null?null:canonical(a),b==null?null:canonical(b));}
 static JSONObject snapshot(JSONObject store)throws JSONException{JSONObject tasks=new JSONObject(),cloud=store.optJSONObject("cloud"),base=cloud==null?new JSONObject():cloud.optJSONObject("base");if(base==null)base=new JSONObject();JSONArray a=store.getJSONArray("tasks"),changes=new JSONArray();for(int i=0;i<a.length();i++){JSONObject t=a.getJSONObject(i);tasks.put(t.getString("id"),payload(t));}Set<String> ids=new TreeSet<>();tasks.keys().forEachRemaining(ids::add);base.keys().forEachRemaining(ids::add);for(String id:ids){JSONObject t=tasks.optJSONObject(id),old=base.optJSONObject(id);if(t!=null){if(old==null||old.optBoolean("deleted")||!eq(t,old.optJSONObject("data")))changes.put(new JSONObject().put("id",id).put("base_revision",old==null?0:old.optLong("revision")).put("deleted",false).put("data",t));}else if(old!=null&&!old.optBoolean("deleted"))changes.put(new JSONObject().put("id",id).put("base_revision",old.optLong("revision")).put("deleted",true).put("data",new JSONObject()));}JSONArray batch=new JSONArray(),dirty=new JSONArray();for(int n=0;n<changes.length();n++){dirty.put(changes.getJSONObject(n).getString("id"));if(n<100)batch.put(changes.get(n));}return new JSONObject().put("tasks",tasks).put("changes",batch).put("dirty",dirty);}
 static void apply(JSONObject store,JSONObject sent,JSONObject response)throws JSONException{JSONObject cloud=store.getJSONObject("cloud"),base=cloud.getJSONObject("base"),before=sent.getJSONObject("tasks"),results=new JSONObject();Map<String,JSONObject> map=new LinkedHashMap<>();JSONArray tasks=store.getJSONArray("tasks"),rs=response.getJSONArray("results");for(int i=0;i<tasks.length();i++){JSONObject t=tasks.getJSONObject(i);map.put(t.getString("id"),t);}for(int i=0;i<rs.length();i++)results.put(rs.getJSONObject(i).getString("id"),rs.getJSONObject(i));Set<String> dirty=new HashSet<>(),outgoing=new HashSet<>();JSONArray dirtyList=sent.optJSONArray("dirty"),batch=sent.getJSONArray("changes");if(dirtyList!=null)for(int n=0;n<dirtyList.length();n++)dirty.add(dirtyList.getString(n));for(int n=0;n<batch.length();n++)outgoing.add(batch.getJSONObject(n).getString("id"));JSONArray rows=response.getJSONArray("rows");for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);String id=row.getString("id");if(dirty.contains(id)&&!outgoing.contains(id))continue;JSONObject old=map.get(id),result=results.optJSONObject(id);boolean unchanged=eq(old==null?null:payload(old),before.optJSONObject(id));if(result!=null&&!result.optBoolean("ok")){if(!unchanged)continue;if(old!=null){JSONObject copy=new JSONObject(old.toString());String title=copy.optString("title");copy.put("id",UUID.randomUUID().toString()).put("title",title.substring(0,Math.min(185,title.length()))+"（同步冲突副本）").put("created",java.time.Instant.now().toString());map.put(copy.getString("id"),copy);}cloud.put("conflicts",cloud.optInt("conflicts")+1);}else if(!unchanged){if(result!=null&&result.optBoolean("ok"))base.put(id,row);continue;}if(row.optBoolean("deleted"))map.remove(id);else{JSONObject t=new JSONObject(row.getJSONObject("data").toString());boolean same=old!=null&&Objects.equals(old.optString("due"),t.optString("due"))&&eq(old.optJSONArray("offsets"),t.optJSONArray("offsets"));t.put("fired",same&&old.optJSONArray("fired")!=null?old.getJSONArray("fired"):new JSONArray());map.put(id,t);}base.put(id,row);}JSONArray out=new JSONArray();for(JSONObject t:map.values())out.put(t);store.put("tasks",out);cloud.put("lastSync",java.time.Instant.now().toString());}
}
